-- Account-month spine. Account master is a current snapshot; it is NOT historical active population.
CREATE OR REPLACE VIEW mart.observed_months AS SELECT DISTINCT DATE_TRUNC('month',event_at_source)::date month_start FROM clean.payments_exact_dedup WHERE event_at_source IS NOT NULL;
CREATE OR REPLACE VIEW mart.account_month_payments AS SELECT account_id,DATE_TRUNC('month',event_at_source)::date month_start,SUM(amount) FILTER(WHERE payment_status='SUCCESS' AND amount>0) gross_success_inr,COUNT(*) FILTER(WHERE payment_status='SUCCESS' AND amount>0) success_rows,COUNT(DISTINCT payment_id) FILTER(WHERE payment_status='SUCCESS' AND amount>0) success_payment_ids FROM clean.payments_exact_dedup GROUP BY 1,2;
CREATE OR REPLACE VIEW mart.account_month_targeting AS SELECT account_id,month_start,COUNT(DISTINCT target_id) target_records,COUNT(DISTINCT campaign_id) campaigns_touched,MAX(priority) max_priority FROM stg.targeting GROUP BY 1,2;
CREATE OR REPLACE VIEW mart.golden_account_month AS SELECT a.account_id,a.borrower_id master_borrower_id,a.dpd,a.risk_segment,a.loan_type,a.outstanding_amount,m.month_start,COALESCE(t.target_records,0) target_records,COALESCE(t.campaigns_touched,0) campaigns_touched,COALESCE(t.max_priority,0) max_priority,COALESCE(p.gross_success_inr,0) gross_success_inr,COALESCE(p.success_rows,0) success_rows,CASE WHEN COALESCE(p.gross_success_inr,0)>0 THEN 1 ELSE 0 END payer_flag FROM stg.accounts a CROSS JOIN mart.observed_months m LEFT JOIN mart.account_month_targeting t USING(account_id,month_start) LEFT JOIN mart.account_month_payments p USING(account_id,month_start);
